//! Bindings to `ntifs.h`, `wdmsec.h`, `ndis.h`, `fwpsk.h` and `fwpmk.h`, generated by `build.rs`
//! with `wdk-build`'s bindgen settings, plus what bindgen cannot translate: macros, inline
//! functions and status codes.

#![allow(
    non_upper_case_globals,
    non_camel_case_types,
    non_snake_case,
    dead_code,
    missing_docs,
    unsafe_op_in_unsafe_fn,
    unknown_lints,
    unnecessary_transmutes,
    unused_imports,
    clippy::all
)]

include!(concat!(env!("OUT_DIR"), "/sys.rs"));

pub type DRIVER_OBJECT = _DRIVER_OBJECT;
pub type DEVICE_OBJECT = _DEVICE_OBJECT;
pub type FILE_OBJECT = _FILE_OBJECT;
pub type IO_STACK_LOCATION = _IO_STACK_LOCATION;

pub const STATUS_SUCCESS: NTSTATUS = 0;
pub const STATUS_PENDING: NTSTATUS = 0x0000_0103;
pub const STATUS_CANCELLED: NTSTATUS = 0xC000_0120_u32 as NTSTATUS;
pub const STATUS_PIPE_EMPTY: NTSTATUS = 0xC000_00D9_u32 as NTSTATUS;
pub const STATUS_NOT_IMPLEMENTED: NTSTATUS = 0xC000_0002_u32 as NTSTATUS;
pub const STATUS_INVALID_PARAMETER: NTSTATUS = 0xC000_000D_u32 as NTSTATUS;
pub const STATUS_INVALID_DEVICE_REQUEST: NTSTATUS = 0xC000_0010_u32 as NTSTATUS;
pub const STATUS_INSUFFICIENT_RESOURCES: NTSTATUS = 0xC000_009A_u32 as NTSTATUS;
pub const STATUS_BUFFER_TOO_SMALL: NTSTATUS = 0xC000_0023_u32 as NTSTATUS;
pub const STATUS_REVISION_MISMATCH: NTSTATUS = 0xC000_0059_u32 as NTSTATUS;
pub const STATUS_INVALID_DEVICE_STATE: NTSTATUS = 0xC000_0184_u32 as NTSTATUS;
pub const STATUS_NOT_SUPPORTED: NTSTATUS = 0xC000_00BB_u32 as NTSTATUS;
pub const STATUS_DEVICE_NOT_READY: NTSTATUS = 0xC000_00A3_u32 as NTSTATUS;

/// `IoGetCurrentIrpStackLocation`, an inline function in `wdm.h`.
///
/// # Safety
///
/// `irp` is a valid IRP the driver owns.
pub unsafe fn current_stack_location(irp: *mut IRP) -> *mut IO_STACK_LOCATION {
    unsafe {
        (*irp)
            .Tail
            .Overlay
            .__bindgen_anon_2
            .__bindgen_anon_1
            .CurrentStackLocation
    }
}

/// Completes `irp` with `status`, and `information` bytes for the caller (`IoCompleteRequest`).
///
/// # Safety
///
/// `irp` is a valid IRP the driver owns; it is not used again.
pub unsafe fn complete(irp: *mut IRP, status: NTSTATUS, information: usize) -> NTSTATUS {
    unsafe {
        (*irp).IoStatus.__bindgen_anon_1.Status = status;
        (*irp).IoStatus.Information = information as _;
        IofCompleteRequest(irp, 0);
    }
    status
}

/// `NDIS_STATUS_SUCCESS` and the others: cast macros, which bindgen skips.
pub const NDIS_STATUS_SUCCESS: NDIS_STATUS = 0;
pub const NDIS_STATUS_PENDING: NDIS_STATUS = STATUS_PENDING;
pub const NDIS_STATUS_RESOURCES: NDIS_STATUS = STATUS_INSUFFICIENT_RESOURCES;
pub const NDIS_STATUS_NOT_SUPPORTED: NDIS_STATUS = STATUS_NOT_SUPPORTED;

/// Indexes in `NetBufferListInfo` (`NDIS_NET_BUFFER_LIST_INFO`): the checksum offload request,
/// the large send (LSO) request, and the 802.1Q tag.
pub const TCP_IP_CHECKSUM_INFO: usize = 0;
pub const TCP_LARGE_SEND_INFO: usize = 2;
pub const IEEE_8021Q_INFO: usize = 4;

/// `NET_BUFFER_LIST_NEXT_NBL`.
///
/// # Safety
///
/// `nbl` points to a valid NET_BUFFER_LIST.
pub unsafe fn nbl_next(nbl: *mut NET_BUFFER_LIST) -> *mut NET_BUFFER_LIST {
    unsafe { (*nbl).__bindgen_anon_1.__bindgen_anon_1.Next }
}

/// Sets `NET_BUFFER_LIST_NEXT_NBL`.
///
/// # Safety
///
/// `nbl` points to a valid NET_BUFFER_LIST the caller owns.
pub unsafe fn set_nbl_next(nbl: *mut NET_BUFFER_LIST, next: *mut NET_BUFFER_LIST) {
    unsafe { (*nbl).__bindgen_anon_1.__bindgen_anon_1.Next = next }
}

/// `NET_BUFFER_LIST_INFO(nbl, i)`, as an integer.
///
/// # Safety
///
/// `nbl` points to a valid NET_BUFFER_LIST.
pub unsafe fn nbl_info(nbl: *mut NET_BUFFER_LIST, i: usize) -> usize {
    unsafe { (*nbl).NetBufferListInfo[i] as usize }
}

/// Sets `NET_BUFFER_LIST_INFO(nbl, i)`.
///
/// # Safety
///
/// `nbl` points to a valid NET_BUFFER_LIST the caller owns.
pub unsafe fn set_nbl_info(nbl: *mut NET_BUFFER_LIST, i: usize, value: usize) {
    unsafe { (*nbl).NetBufferListInfo[i] = value as *mut core::ffi::c_void }
}

/// `NET_BUFFER_LIST_STATUS`, set.
///
/// # Safety
///
/// `nbl` points to a valid NET_BUFFER_LIST the caller owns.
pub unsafe fn set_nbl_status(nbl: *mut NET_BUFFER_LIST, status: NDIS_STATUS) {
    unsafe { (*nbl).__bindgen_anon_2.Status = status }
}

/// `NET_BUFFER_NEXT_NB`.
///
/// # Safety
///
/// `nb` points to a valid NET_BUFFER.
pub unsafe fn nb_next(nb: *mut NET_BUFFER) -> *mut NET_BUFFER {
    unsafe { (*nb).__bindgen_anon_1.__bindgen_anon_1.Next }
}

/// `NET_BUFFER_FIRST_MDL`.
///
/// # Safety
///
/// `nb` points to a valid NET_BUFFER.
pub unsafe fn nb_first_mdl(nb: *mut NET_BUFFER) -> *mut MDL {
    unsafe { (*nb).__bindgen_anon_1.__bindgen_anon_1.MdlChain }
}

/// `NET_BUFFER_LIST_FIRST_NB`.
///
/// # Safety
///
/// `nbl` points to a valid NET_BUFFER_LIST.
pub unsafe fn nbl_first_nb(nbl: *mut NET_BUFFER_LIST) -> *mut NET_BUFFER {
    unsafe { (*nbl).__bindgen_anon_1.__bindgen_anon_1.FirstNetBuffer }
}

/// `NET_BUFFER_DATA_LENGTH`.
///
/// # Safety
///
/// `nb` points to a valid NET_BUFFER.
pub unsafe fn nb_data_length(nb: *mut NET_BUFFER) -> u32 {
    unsafe {
        (*nb)
            .__bindgen_anon_1
            .__bindgen_anon_1
            .__bindgen_anon_1
            .DataLength
    }
}

/// `IoGetRemainingStackSize`, an inline function in `wdm.h`.
pub fn remaining_stack() -> usize {
    let (mut low, mut high) = (0, 0);
    // SAFETY: plain out-parameters.
    unsafe { IoGetStackLimits(&mut low, &mut high) };
    let here = &low as *const _ as usize;
    here.saturating_sub(low as usize)
}

/// A NUL-terminated UTF-16 string from an ASCII literal.
macro_rules! w {
    ($s:literal) => {{
        const S: &str = concat!($s, "\0");
        const W: [u16; S.len()] = {
            let b = S.as_bytes();
            let mut w = [0u16; S.len()];
            let mut i = 0;
            while i < b.len() {
                w[i] = b[i] as u16;
                i += 1;
            }
            w
        };
        &W
    }};
}
pub(crate) use w;

/// A `UNICODE_STRING` over a static NUL-terminated UTF-16 string.
pub fn unicode(s: &'static [u16]) -> UNICODE_STRING {
    UNICODE_STRING {
        Length: ((s.len() - 1) * 2) as u16,
        MaximumLength: (s.len() * 2) as u16,
        Buffer: s.as_ptr().cast_mut(),
    }
}
